import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type AppleFlashlightProps = Record<string, any>;

const cap = (val: number) => Math.min(1, Math.max(0, val));

const AppleFlashlight: React.FC<AppleFlashlightProps> = ({
  backgroundColor = "#080808",
  transparentBackground = true,
  durationInSeconds = 6,
  beamPrimaryColor = "#ffffff",
  beamSecondaryColor = "#b8f2e6",
  iconColor = "#ffffff",
  beamWidth = 40,
  beamHeight = 40,
  beamRounding = 30,
  beamIntensity = 1,
  edgeSoftness = 20,
  showDropShadow = true,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // ---------------------------------------------------------------------------
  // TIMING CONFIGURATION (Sequential Apple-style Flow)
  // ---------------------------------------------------------------------------
  const entryStart = 5;
  const beamRevealStart = entryStart + fps * 0.4;
  const expandStart = beamRevealStart + fps * 0.4;
  
  // Ensure we have enough time before exit for safe timing on short durations
  const exitStart = Math.max(expandStart + fps * 0.5, durationInFrames - fps);
  
  // Calculate phases to allow expanding, holding, and contracting back to skinny
  const availableTimeForBeam = exitStart - expandStart;
  const expandDuration = Math.min(fps * 0.6, availableTimeForBeam * 0.5);
  const contractDuration = Math.min(fps * 0.6, availableTimeForBeam * 0.5);
  
  const contractStart = exitStart - contractDuration;
  const fadeStart = expandStart + expandDuration;

  // Smooth Apple-like easing curve
  const appleEase = Easing.bezier(0.25, 0.1, 0.25, 1);

  // ---------------------------------------------------------------------------
  // 1. ENTRANCE (Subtle Slide up & Fade in)
  // ---------------------------------------------------------------------------
  const entryEaseProgress = interpolate(
    frame,
    [entryStart, entryStart + fps * 0.8],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: appleEase,
    }
  );

  const entryY = interpolate(entryEaseProgress, [0, 1], [50, 0]);
  const entryOpacity = interpolate(entryEaseProgress, [0, 1], [0, 1]);

  // Beam appears sequentially after base enters
  const beamRevealProgress = interpolate(
    frame,
    [beamRevealStart, beamRevealStart + fps * 0.3],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.ease),
    }
  );

  // ---------------------------------------------------------------------------
  // 2. BEAM EXPANSION, CONTRACT & SHAPING (Skinny -> Wide -> Skinny)
  // ---------------------------------------------------------------------------
  const expandPhase = interpolate(
    frame,
    [expandStart, expandStart + expandDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: appleEase,
    }
  );

  const contractPhase = interpolate(
    frame,
    [contractStart, contractStart + contractDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: appleEase,
    }
  );

  // Combines both phases: goes 0 -> 1 -> 0
  const beamWidthProgress = expandPhase - contractPhase;

  // Beam Layout Dimensions
  const beamContainerWidth = 600; // Fixed width for precise SVG coordinate mapping
  
  // Map beamHeight (10-100) to actual canvas height (20% to 80% of screen)
  const minBeamH = height * 0.2;
  const maxBeamH = height * 0.8;
  const actualBeamHeight = minBeamH + ((beamHeight - 10) / 90) * (maxBeamH - minBeamH);

  // Map beamWidth (10-100) to top expansion spread
  const minSpread = 12.66; // Matches exact width of the flashlight lens below
  const maxSpread = 350; // Increased to flare out significantly wider horizontally
  const spread = minSpread + ((beamWidth - 10) / 90) * (maxSpread - minSpread);
  const wideMainTopLeft = 50 - spread / 2;
  const wideMainTopRight = 50 + spread / 2;

  // Main Beam Coordinates (Base width is exactly 12.66% of 600px = 76px)
  const mainBaseLeft = 43.67;
  const mainBaseRight = 56.33;
  const currentTopLeft = interpolate(beamWidthProgress, [0, 1], [mainBaseLeft, wideMainTopLeft]);
  const currentTopRight = interpolate(beamWidthProgress, [0, 1], [mainBaseRight, wideMainTopRight]);

  // Map beamRounding to outward bow offset
  const bow = (beamRounding / 100) * 40; 
  const mainRightCpX = ((currentTopRight + mainBaseRight) / 2) + bow;
  const mainLeftCpX = ((currentTopLeft + mainBaseLeft) / 2) - bow;

  const mainBeamPath = `
    M ${currentTopLeft} 0
    L ${currentTopRight} 0
    Q ${mainRightCpX} 50, ${mainBaseRight} 100
    L ${mainBaseLeft} 100
    Q ${mainLeftCpX} 50, ${currentTopLeft} 0
    Z
  `;

  // Hotspot Coordinates (Slightly narrower than main beam)
  const hotspotMinSpread = 6;
  const hotspotMaxSpread = 180; // Proportionally increased to match the wider main flare
  const hSpread = hotspotMinSpread + ((beamWidth - 10) / 90) * (hotspotMaxSpread - hotspotMinSpread);
  const wideHotspotTopLeft = 50 - hSpread / 2;
  const wideHotspotTopRight = 50 + hSpread / 2;
  
  const hotspotBaseLeft = 47;
  const hotspotBaseRight = 53;
  const currentHotspotTopLeft = interpolate(beamWidthProgress, [0, 1], [hotspotBaseLeft, wideHotspotTopLeft]);
  const currentHotspotTopRight = interpolate(beamWidthProgress, [0, 1], [hotspotBaseRight, wideHotspotTopRight]);
  
  const hotspotRightCpX = ((currentHotspotTopRight + hotspotBaseRight) / 2) + (bow * 0.6); 
  const hotspotLeftCpX = ((currentHotspotTopLeft + hotspotBaseLeft) / 2) - (bow * 0.6);

  const hotspotPath = `
    M ${currentHotspotTopLeft} 0
    L ${currentHotspotTopRight} 0
    Q ${hotspotRightCpX} 50, ${hotspotBaseRight} 100
    L ${hotspotBaseLeft} 100
    Q ${hotspotLeftCpX} 50, ${currentHotspotTopLeft} 0
    Z
  `;

  // ---------------------------------------------------------------------------
  // 3. MOTION BLUR & SOFTNESS
  // ---------------------------------------------------------------------------
  const maxBlur = 40;
  const baseSoftness = (edgeSoftness / 100) * maxBlur;
  const motionBlurXAmount = interpolate(beamWidthProgress, [0, 0.5, 1], [0, 15, 0]);
  
  const finalBlurX = baseSoftness + motionBlurXAmount + 0.1; 
  const finalBlurY = baseSoftness + 0.1;
  const hotspotBlurX = (baseSoftness * 0.4) + (motionBlurXAmount * 0.5) + 0.1;
  const hotspotBlurY = (baseSoftness * 0.4) + 0.1;

  // ---------------------------------------------------------------------------
  // 4. INTENSITY FADE (Dims gradually after expansion)
  // ---------------------------------------------------------------------------
  const intensityFade = interpolate(
    frame,
    [fadeStart, fadeStart + fps * 1.5],
    [1, 0.35],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.ease),
    }
  );

  // ---------------------------------------------------------------------------
  // 5. EXIT TRANSITION
  // ---------------------------------------------------------------------------
  const exitProgress = interpolate(frame, [exitStart, durationInFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.ease),
  });

  const exitY = interpolate(exitProgress, [0, 1], [0, 100]);
  const globalOpacity = interpolate(exitProgress, [0, 0.8], [1, 0], {
    extrapolateRight: "clamp",
  });
  const exitBeamCollapse = interpolate(exitProgress, [0, 0.5], [1, 0], {
    extrapolateRight: "clamp",
  });

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Positioning
  const flashlightBottom = height * 0.15;
  const flashlightCapHeight = 28;
  const flashlightHandleHeight = 78;
  const flashlightMargin = 4;
  const totalFlashlightHeight = flashlightCapHeight + flashlightHandleHeight + flashlightMargin;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter" }}>
      {/* 
        Master Container
      */}
      <AbsoluteFill
        style={{
          transform: `translateY(${entryY + exitY}px)`,
          opacity: entryOpacity * globalOpacity,
        }}
      >
        {/* 
          Beam Container 
        */}
        <div
          style={{
            position: "absolute",
            bottom: flashlightBottom + totalFlashlightHeight,
            left: "50%",
            transform: `translateX(-50%) scaleY(${beamRevealProgress * exitBeamCollapse})`,
            transformOrigin: "bottom center",
            width: beamContainerWidth,
            height: actualBeamHeight,
            overflow: "visible",
            opacity: intensityFade,
          }}
        >
          <svg
            width="100%"
            height="100%"
            viewBox="0 0 100 100"
            preserveAspectRatio="none"
            style={{ overflow: "visible" }}
          >
            <defs>
              <filter id="mainBeamFilter" x="-100%" y="-100%" width="300%" height="300%">
                <feGaussianBlur stdDeviation={`${finalBlurX} ${finalBlurY}`} />
              </filter>

              <filter id="hotspotFilter" x="-100%" y="-100%" width="300%" height="300%">
                <feGaussianBlur stdDeviation={`${hotspotBlurX} ${hotspotBlurY}`} />
              </filter>

              {/* Diffused Outer Beam Gradient */}
              <linearGradient id="mainBeamGrad" x1="0%" y1="100%" x2="0%" y2="0%">
                <stop offset="0%" stopColor={beamPrimaryColor} stopOpacity={cap(0.95 * beamIntensity)} />
                <stop offset="30%" stopColor={beamSecondaryColor} stopOpacity={cap(0.5 * beamIntensity)} />
                <stop offset="100%" stopColor={beamSecondaryColor} stopOpacity="0" />
              </linearGradient>

              {/* Central Bright Hotspot Gradient */}
              <linearGradient id="hotspotGrad" x1="0%" y1="100%" x2="0%" y2="0%">
                <stop offset="0%" stopColor={beamPrimaryColor} stopOpacity={cap(1 * beamIntensity)} />
                <stop offset="25%" stopColor={beamPrimaryColor} stopOpacity={cap(0.8 * beamIntensity)} />
                <stop offset="80%" stopColor={beamPrimaryColor} stopOpacity="0" />
              </linearGradient>
            </defs>

            {/* Main Soft Cone Beam */}
            <path
              d={mainBeamPath}
              fill="url(#mainBeamGrad)"
              filter="url(#mainBeamFilter)"
              style={{
                transition: "none",
              }}
            />

            {/* Core Focused Hotspot */}
            <path
              d={hotspotPath}
              fill="url(#hotspotGrad)"
              filter="url(#hotspotFilter)"
              style={{
                transition: "none",
                opacity: 0.9,
              }}
            />
          </svg>
        </div>

        {/* 
          Flashlight Icon Assembly 
        */}
        <div
          style={{
            position: "absolute",
            bottom: flashlightBottom,
            left: "50%",
            transform: "translateX(-50%)",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            width: 80,
            height: totalFlashlightHeight,
          }}
        >
          {/* Base Light Glow Source (Emanating directly from lens) */}
          <div
            style={{
              position: "absolute",
              top: -2,
              width: 50,
              height: 12,
              backgroundColor: beamPrimaryColor,
              borderRadius: "50%",
              filter: "blur(8px)",
              opacity: cap(intensityFade * beamRevealProgress * beamIntensity * 0.8),
              zIndex: 3,
            }}
          />

          {/* Flashlight Physical Body with optional Drop Shadow */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              filter: showDropShadow ? "drop-shadow(0px 20px 30px rgba(0,0,0,0.6))" : "none",
              zIndex: 2,
            }}
          >
            {/* Flashlight Lens/Top Cap */}
            <div
              style={{
                width: 76,
                height: flashlightCapHeight,
                backgroundColor: iconColor,
                borderRadius: "14px 14px 6px 6px",
                boxShadow: "0 -4px 12px rgba(255,255,255,0.15)",
              }}
            />

            {/* Flashlight Handle/Body */}
            <div
              style={{
                width: 52,
                height: flashlightHandleHeight,
                backgroundColor: iconColor,
                borderRadius: "6px 6px 18px 18px",
                marginTop: flashlightMargin,
              }}
            />
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default AppleFlashlight;